import re
import ast
import operator as op
import torch
from datasets import load_dataset
from transformers import AutoTokenizer, AutoModelForCausalLM

MODEL = "meta-llama/Llama-3.2-1B-Instruct"  # swap if needed
DEVICE = "cuda" if torch.cuda.is_available() else "cpu"

tok = AutoTokenizer.from_pretrained(MODEL)
model = AutoModelForCausalLM.from_pretrained(
    MODEL,
    torch_dtype=torch.float16 if DEVICE == "cuda" else None,
)
model.to(DEVICE)

# ---------------- LLM utils ----------------
@torch.no_grad()
def generate(prompt, max_new_tokens=256, temperature=0.7):
    inputs = tok(prompt, return_tensors="pt").to(DEVICE)
    out = model.generate(
        **inputs,
        do_sample=True,
        temperature=temperature,
        max_new_tokens=max_new_tokens,
        pad_token_id=tok.eos_token_id,
    )
    text = tok.decode(out[0], skip_special_tokens=True)
    return text[len(prompt):].strip()

# ---------------- safe arithmetic eval ----------------
ALLOWED_BINOPS = {
    ast.Add: op.add,
    ast.Sub: op.sub,
    ast.Mult: op.mul,
    ast.Div: op.truediv,
    ast.FloorDiv: op.floordiv,
    ast.Mod: op.mod,
    ast.Pow: op.pow,
}
ALLOWED_UNARYOPS = {ast.UAdd: op.pos, ast.USub: op.neg}

class SafeEvalError(Exception):
    pass

def _eval(node, env):
    if isinstance(node, ast.Expression):
        return _eval(node.body, env)
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)):
        return node.value
    if isinstance(node, ast.Name):
        if node.id not in env:
            raise SafeEvalError(f"Undefined variable: {node.id}")
        return env[node.id]
    if isinstance(node, ast.BinOp) and type(node.op) in ALLOWED_BINOPS:
        return ALLOWED_BINOPS[type(node.op)](_eval(node.left, env), _eval(node.right, env))
    if isinstance(node, ast.UnaryOp) and type(node.op) in ALLOWED_UNARYOPS:
        return ALLOWED_UNARYOPS[type(node.op)](_eval(node.operand, env))
    if isinstance(node, ast.Call):
        raise SafeEvalError("Function calls not allowed")
    raise SafeEvalError(f"Disallowed syntax: {type(node).__name__}")

def safe_eval_expr(expr, env):
    try:
        tree = ast.parse(expr, mode="eval")
        return _eval(tree, env)
    except Exception as e:
        raise SafeEvalError(str(e))

def parse_calc_and_final(text):
    # Expect:
    # CALC:
    # x = ...
    # answer = ...
    # FINAL: ...
    m_final = re.search(r"FINAL:\s*([^\n]+)", text)
    final = m_final.group(1).strip() if m_final else None

    m_calc = re.search(r"CALC:\s*(.*?)(?:\n\s*FINAL:|\Z)", text, flags=re.S)
    calc_block = m_calc.group(1).strip() if m_calc else ""
    lines = [ln.strip() for ln in calc_block.splitlines() if ln.strip()]
    return lines, final

def verify_calc(lines, final_str):
    """Return (passed: bool, answer_value: float|None)."""
    if not lines or final_str is None:
        return False, None
    env = {}
    answer_val = None
    for ln in lines:
        # allow comments after '#'
        ln = ln.split("#", 1)[0].strip()
        if not ln:
            continue
        if "=" in ln:
            var, expr = ln.split("=", 1)
            var = var.strip()
            expr = expr.strip()
            if not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", var):
                return False, None
            val = safe_eval_expr(expr, env)
            env[var] = val
            if var == "answer":
                answer_val = val
        else:
            # expression-only line allowed but ignored
            _ = safe_eval_expr(ln, env)

    if answer_val is None:
        return False, None

    # Compare to FINAL: allow integer formatting differences
    # Extract first number from FINAL
    m_num = re.search(r"-?\d+(?:\.\d+)?", final_str)
    if not m_num:
        return False, answer_val
    final_num = float(m_num.group(0))

    # tolerant match for float ops
    if abs(final_num - float(answer_val)) > 1e-6:
        return False, answer_val
    return True, answer_val

# ---------------- prompts ----------------
def l2m_decompose_prompt(q):
    return (
        "Decompose the problem into 3-6 minimal subproblems. Output only a numbered list.\n\n"
        f"Problem: {q}\n"
    )

def pc_l2m_solve_prompt(q, steps):
    return (
        "Solve using the subproblems. Keep reasoning brief. "
        "You MUST include a CALC section with only safe arithmetic and assignments. "
        "In CALC, use Python-style arithmetic with numbers and + - * / // % ** parentheses, and variables. "
        "End CALC by assigning the final numeric result to variable 'answer'. "
        "Then output FINAL: <number>.\n\n"
        f"Problem: {q}\n\nSubproblems:\n{steps}\n\n"
        "Format exactly:\n"
        "CALC:\n"
        "<one assignment/expression per line>\n"
        "FINAL: <number>\n"
    )

def cot_prompt(q):
    return (
        "Solve the problem. Show concise reasoning, then give the final answer as 'FINAL: <answer>'.\n\n"
        f"Problem: {q}\n"
    )

def parse_final(text):
    m = re.search(r"FINAL:\s*([^\n]+)", text)
    return m.group(1).strip() if m else None

# ---------------- method: PC-L2M ----------------
@torch.no_grad()
def pc_l2m_answer(q, N=5):
    verified_answers = []  # list of (answer_str, calc_len)
    fallback_answers = []

    for _ in range(N):
        steps = generate(l2m_decompose_prompt(q), max_new_tokens=128, temperature=0.9)
        out = generate(pc_l2m_solve_prompt(q, steps), max_new_tokens=256, temperature=0.7)
        calc_lines, final_str = parse_calc_and_final(out)
        fallback_answers.append(final_str or "")
        try:
            ok, ans_val = verify_calc(calc_lines, final_str)
        except Exception:
            ok, ans_val = False, None
        if ok:
            # canonicalize as integer if very close
            if abs(ans_val - round(ans_val)) < 1e-6:
                ans_txt = str(int(round(ans_val)))
            else:
                ans_txt = str(ans_val)
            verified_answers.append((ans_txt, len(calc_lines)))

    if verified_answers:
        # verified majority vote, tie-break by shorter CALC (simplicity)
        counts = {}
        for a, clen in verified_answers:
            counts.setdefault(a, []).append(clen)
        # score by (frequency, -avg_calc_len)
        best = sorted(counts.items(), key=lambda kv: (len(kv[1]), -(-sum(kv[1]) / len(kv[1]))),), reverse=True)[0][0]
        return best

    # fallback: self-consistency on FINAL strings (weak)
    # pick most common numeric token
    nums = []
    for fs in fallback_answers:
        if not fs:
            continue
        m = re.search(r"-?\d+(?:\.\d+)?", fs)
        if m:
            nums.append(m.group(0))
    if not nums:
        out = generate(cot_prompt(q), max_new_tokens=256, temperature=0.7)
        return parse_final(out) or ""
    return max(set(nums), key=nums.count)

# ---------------- evaluation ----------------
def eval_gsm8k(n=200, N=5):
    ds = load_dataset("gsm8k", "main", split="test").select(range(n))
    correct = 0
    for ex in ds:
        pred = pc_l2m_answer(ex["question"], N=N)
        gold = ex["answer"].split("####")[-1].strip()
        if pred is not None and pred.strip() == gold:
            correct += 1
    return correct / n

if __name__ == "__main__":
    acc = eval_gsm8k(n=50, N=3)
    print({"accuracy": acc})
